mapper.select:
    		select pos_num sessionendNum,pos.asset_code assetcode,ca.ASSET_TYPE assettype,ca.ASSET_TYPE2 assettype2 from
			CHB_BOT_AST_POS pos
			left join CHB_ASSET_INFO ca on ca.ASSET_CODE=pos.ASSET_CODE
			and CA.STATUS !='D'
			where PLAN_ASSET_ID=#{assetcode, jdbcType = VARCHAR}
			and pos_date=(select max(pos_date) from CHB_BOT_AST_POS
			where PLAN_ASSET_ID=#{assetcode, jdbcType = VARCHAR} 
			and pos_date<=#{endDate, jdbcType = DATE}
			and status !='D'
			)

SELECT 't3_36_amt' propertycode, ( SELECT NVL(SUM(CMAP.ASSETVALUE_B), 0) FROM CHB_MONTH_ASSET_POSITION CMAP
left join DATA_AUTH_NOTIFY_INST di on cmap.prod_id=di.business_id and di.model_type = '02' AND DI.DATA_TYPE= 'PTL01'
LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE
WHERE CMAP.STARTDATE = #{startDate, jdbcType = DATE} AND INFO.ASSET_TYPE2 IN ('1106', '2401', '1303', '2403','2402','2499')
and di.institution_code=#{org, jdbcType=VARCHAR}
) AS indInvestmentAmount, ( SELECT NVL(SUM(CMAP.ASSETVALUE_B), 0) FROM CHB_MONTH_ASSET_POSITION CMAP
left join DATA_AUTH_NOTIFY_INST di on cmap.prod_id=di.business_id and di.model_type = '02' AND DI.DATA_TYPE= 'PTL01'
LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE
WHERE CMAP.STARTDATE = #{lastStartDate, jdbcType = DATE} AND INFO.ASSET_TYPE2 IN ('1106', '2401', '1303', '2403','2402','2499')
and di.institution_code=#{org, jdbcType=VARCHAR}
) AS lastIndInvestmentAmount, ( SELECT NVL(SUM(CMAP.ASSETVALUE_B), 0) FROM CHB_MONTH_ASSET_POSITION CMAP
left join DATA_AUTH_NOTIFY_INST di on cmap.prod_id=di.business_id and di.model_type = '02' AND DI.DATA_TYPE= 'PTL01'
LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE
WHERE CMAP.STARTDATE = #{startDate, jdbcType = DATE} AND (INFO.ASSET_TYPE2 IN ('1301', '1305', '1302', '1399') or (INFO.ASSET_TYPE2 ='1299' and INFO.IN_ASSET_TYPE IN ('01','02')))
and di.institution_code=#{org, jdbcType=VARCHAR}
) AS otherAmount, ( SELECT NVL(SUM(CMAP.ASSETVALUE_B), 0) FROM CHB_MONTH_ASSET_POSITION CMAP
left join DATA_AUTH_NOTIFY_INST di on cmap.prod_id=di.business_id and di.model_type = '02' AND DI.DATA_TYPE= 'PTL01'
LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE
WHERE CMAP.STARTDATE = #{lastStartDate, jdbcType = DATE} AND (INFO.ASSET_TYPE2 IN ('1301', '1305', '1302', '1399') or (INFO.ASSET_TYPE2 ='1299' and INFO.IN_ASSET_TYPE IN ('01','02')))
and di.institution_code=#{org, jdbcType=VARCHAR}
) AS lastOtherAmount, ( select REPLACE(to_char(wm_concat(t.remark)),',','、') remark from ( select t1.asset_name||'+'||to_char(round(t1.balance/10000,2)) AS remark ,t1.balance as balance,t1.posAmt as posAmt,row_number() over(order by t1.balance desc) as idx
from( select coalesce(info.asset_name,case when info.asset_type2 in ('1108','1902') then info.mdate-info.vdate||'天回购' when info.asset_type2 in ('1107','1901') then info.mdate-info.vdate||'天拆借' end, info.asset_code,'现金')as asset_name, sum(nvl(CMAP.ASSETVALUE_B,0)) as balance, sum(nvl(data.pos_amt,0)) as posAmt from chb_month_asset_position cmap
left join DATA_AUTH_NOTIFY_INST di on cmap.prod_id=di.business_id and di.model_type = '02' AND DI.DATA_TYPE= 'PTL01'
left join chb_asset_info info ON cmap.asset_code=info.asset_code
left join chb_assets_basis_data data on cmap.asset_code=data.asset_id and data.value_date=#{endDate, jdbcType = DATE} and cmap.prod_id =data.prod_id
left join chb_assets_basis_data_nobtm data on cmap.asset_code=data.asset_id and data.value_date=#{endDate, jdbcType = DATE} and cmap.prod_id =data.prod_id
where CMAP.STARTDATE = #{startDate, jdbcType = DATE} and cmap.ASSETVALUE_B is not null AND (INFO.ASSET_TYPE2 IN ('1301', '1305', '1302', '1399') or (INFO.ASSET_TYPE2 ='1299' and INFO.IN_ASSET_TYPE IN ('01','02')))
and di.institution_code=#{org, jdbcType=VARCHAR}
group by coalesce(info.asset_name,case when info.asset_type2 in ('1108','1902') then info.mdate-info.vdate||'天回购' when info.asset_type2 in ('1107','1901') then info.mdate-info.vdate||'天拆借' end, info.asset_code,'现金') )t1 order by t1.balance desc ) t where t.idx<= 3 or t.posAmt>=1000000000 ) as remark
FROM DUAL

SELECT
't3_40_amt' propertycode,
't3_41_amt' propertycode,
't3_42_amt' propertycode,
't3_43_amt' propertycode,
't3_44_amt' propertycode,
't3_45_amt' propertycode,
( SELECT NVL(SUM(CMAP.ASSETVALUE_B), 0) FROM CHB_MONTH_ASSET_POSITION CMAP
left join DATA_AUTH_NOTIFY_INST di on cmap.prod_id=di.business_id and di.model_type = '02' AND DI.DATA_TYPE= 'PTL01'
LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE left join mst_customer_info_add mst on coalesce(info.chb_issuer_id,info.manager_id,info.financie)=mst.customer_id
WHERE 1=1
and CMAP.STARTDATE = #{startDate, jdbcType = DATE}
and info.asset_type2 in ('1101','1110','1109','1111','1102','1112','1113','1114','1115','1116','1117')
and mst.IS_GOV='Y'
and mst.PARTY_TYPE2='01'
/*****1.产能过剩行业：根据系统参数配置，取所属行业属于“产能过剩企业”的机构； 目前暂时只考虑二级行业分类**/ and (instr(#{INDUSTRY1, jdbcType=VARCHAR},mst.INDUSTRY) >0 or instr(#{INDUSTRY2, jdbcType=VARCHAR},mst.INDUSTRY2) >0 or instr(#{INDUSTRY3, jdbcType=VARCHAR},mst.INDUSTRY3) >0 or instr(#{INDUSTRY4, jdbcType=VARCHAR},mst.INDUSTRY4) >0)
and mst.INDUSTRY in ('04','07','14')
/****2.异地业务：根据系统参数配置，取所属省/市非本地的机构.本地字段可多选*/ and not exists ( SELECT 1 FROM SYS_PARA P where PARA_CODE = 'SVR_LOCAL_AREA' AND (instr(P.PARAM_VALUE,mst.PROVINCE) >0 OR instr(P.PARAM_VALUE,mst.CITY) >0) )
/****3.是否股东及其关联方:取市场机构信息中，“是否股东及其关联方”为“是”的机构。*/ and mst.IS_SHAREHOLDER_RELATED = '01'
and di.institution_code=#{org, jdbcType=VARCHAR}
) AS sessionendNum, ( SELECT NVL(SUM(CMAP.ASSETVALUE_B), 0) FROM CHB_MONTH_ASSET_POSITION CMAP
left join DATA_AUTH_NOTIFY_INST di on cmap.prod_id=di.business_id and di.model_type = '02' AND DI.DATA_TYPE= 'PTL01'
LEFT JOIN CHB_ASSET_INFO INFO ON CMAP.ASSET_CODE = INFO.ASSET_CODE left join mst_customer_info_add mst on coalesce(info.chb_issuer_id,info.manager_id,info.financie)=mst.customer_id
WHERE 1=1
